// SIMULATED catalog: robot components, read-only diagnostics, state-changing operations,
// verification checks and metric definitions. Text in [[double brackets]] is a glossary term.
// Every result is computed from the shared Sim state, never from scenario text.
import { STOPPED_STATES, zoneOf, aisleAt, ZONE_AP, SERVICES, SERVICE_DEPS, STATIONS, CHARGERS } from './engine.js';
import { round, fmtDur } from '../util.js';

const yes = (b) => (b ? 'yes' : 'no');
const pct = (v) => (v == null ? 'no data' : `${Math.round(v * 100)}%`);

