// ----------------------------------------------------------------------------- read-only diagnostics
const P = (question, options) => ({ question, options });
const rec = (sim, rid) => sim.robot(rid);

function recentCodes(sim, filter, win = 900) {
  const t0 = sim.s.t - win; const out = {};
  for (const e of sim.s.logs) if (e.t > t0 && filter(e)) out[e.code] = (out[e.code] || 0) + 1;
  return out;
}

