// sandbox tests: run in a cloned simulation so production is untouched
export const SANDBOX_TESTS = {
  sandbox_restart: { label: 'Sandbox: controlled restart of the robot, observe 3 min', target: 'robot', skill: 'software', what: 'Clones the current system state and restarts the robot in the clone only.', when: 'Before restarting in production — to learn whether a restart would help or hide evidence.', evidence: 'Whether the symptom persists after a restart.', limits: 'The sandbox copies state but not every real-world condition.', ops: 'None in production.',
    predict: P('In the sandbox, after a restart, will the robot complete work again?', [['persists', 'No — the symptom persists'], ['clears', 'Yes — it recovers']]),
    run(sim, p) { const c = sim.clone(); const before = c.robot(p.robot).tasksDone; c.operate('restart_robot', { robot: p.robot }); c.run(180); const r = c.robot(p.robot); const done = r.tasksDone - before; const ok = done > 0 && !STOPPED_STATES.includes(r.state); return { outcome: ok ? 'clears' : 'persists', summary: `Sandbox: after restart ${p.robot} completed ${done} task(s) in 3 min; now ${r.state}.${c.s.fm.assignments[p.robot] && !r.taskId ? ' Fleet manager still holds an assignment the robot does not have.' : ''}`, rows: [['Tasks completed (3 min)', done], ['State after', r.state], ['Local diagnostic buffer after restart', 'erased (only in sandbox)']], facts: [`Sandbox restart of ${p.robot}: ${done} tasks completed in 3 min, ended ${r.state}`] }; } },
  sandbox_stop_test: { label: 'Sandbox: stop-behaviour test (simulated E-stop)', target: 'robot', skill: 'verification', what: 'In a clone, opens the E-stop circuit while the robot drives and checks it stops and holds its task safely.', when: 'After a repair to the drive or safety system, before returning to service.', evidence: 'Stop response and task handling.', limits: 'Simulated; real safety validation follows the employer\'s certified procedure.', ops: 'None in production.',
    predict: P('Will the robot stop and keep its task record consistent?', [['pass', 'Yes'], ['fail', 'No']]),
    run(sim, p) { const c = sim.clone(); const r = c.robot(p.robot); r.estop = true; c.run(2); const stopped = r.state === 'estop'; r.estop = false; c.run(5); return { outcome: stopped ? 'pass' : 'fail', summary: `Sandbox: ${p.robot} ${stopped ? 'entered estop within 0.5 s, drive power removed; resumed after reset' : 'did not stop'}.`, rows: [['Stopped', yes(stopped)], ['Task after reset', r.taskId || 'none']], facts: [`Sandbox stop test on ${p.robot}: ${stopped ? 'pass' : 'fail'}`] }; } },
  sandbox_comms: { label: 'Sandbox: interrupt communications for 10 s', target: 'robot', skill: 'verification', what: 'In a clone, drops the robot link for 10 s and observes safe stop, reconnect and task handling.', when: 'To understand how the system behaves under interrupted comms before blaming a robot.', evidence: 'Safe-stop and recovery behaviour, duplicate-delivery handling.', limits: 'Simulated network.', ops: 'None in production.',
    predict: P('After the link returns, will the robot resume without duplicate work?', [['pass', 'Yes — resumes, duplicates ignored'], ['fail', 'No']]),
    run(sim, p) { const c = sim.clone(); const r = c.robot(p.robot); r.dropUntil = c.s.t + 10; c.run(30); const dup = c.s.counters.dupPickPrevented - sim.s.counters.dupPickPrevented; const ok = !STOPPED_STATES.includes(r.state) || r.state === 'blocked' || r.state === 'loc_lost'; return { outcome: ok && dup === 0 ? 'pass' : 'fail', summary: `Sandbox: ${p.robot} ${ok ? 'resumed' : 'did not resume'}; duplicate picks prevented ${dup}; state ${r.state}.`, rows: [], facts: [`Sandbox comms interruption on ${p.robot}: ${ok ? 'resumed' : 'stuck'} (${r.state})`] }; } },
};

export function sandboxAction(sim, op, params, seconds = 300) {
  const c = sim.clone();
  const before = { q: c.queueDepth(), age: c.oldestOpenAge() };
  const res = c.operate(op, params);
  const done0 = c.s.counters.completed;
  c.run(seconds);
  const after = { q: c.queueDepth(), age: c.oldestOpenAge(), done: c.s.counters.completed - done0, err: c.serviceErrorRate('inventory-service', 120), alarms: c.activeAlarms().map((a) => a.key) };
  const checks = {};
  for (const ck of Object.values(CHECKS)) checks[ck.id] = ck.run(c, { ...params, since: sim.s.t });
  return { res, before, after, checks, seconds };
}

